**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int policzWystapienia(const string& tekst, const string& wzorzec) {
    int cnt = 0;
    int pos = 0;
    while ((pos = tekst.find(wzorzec, pos)) != (int)string::npos) {
        cnt++;
        pos++;
    }
    return cnt;
}

int main() {
    ifstream plik("dane.txt");
    string wzorzec;
    plik >> wzorzec;
    cout << "Wzorzec: " << wzorzec << endl;
    string s;
    int suma = 0;
    while (plik >> s) {
        int ile = policzWystapienia(s, wzorzec);
        cout << s << ": " << ile << endl;
        suma += ile;
    }
    cout << "Lacznie: " << suma << endl;
    return 0;
}
```

**Wyjasnienie**: Metoda `find(wzorzec, pos)` szuka wzorca poczawszy od pozycji `pos`. Po znalezieniu przesuwamy `pos` o 1 (nie o dlugosc wzorca), co pozwala wykryc nakladajace sie wystapienia.

